import { AUTO_COMMIT_DELAY_MS, type CommitRequest, type MarkdownFile, type MoveFile, type WriteFilesRequest } from './data_types'

import { markdownParsingService } from '../services/data/markdown_parsing_service'
import type { OpenDocumentSaveReference } from '../services/open_files_service'
import type { Card } from './data_types'

type DelayId = number

interface CommitBatcherOperations {
    commitFiles(request: CommitRequest): Promise<unknown>
    pushCommittedFiles(request: CommitRequest): Promise<unknown>
    requireCardByInternalId(internalId: string): Card
    writeFiles(request: WriteFilesRequest): Promise<unknown>
}

export const COMMIT_BATCHER_FLUSH_FAILED_EVENT = 'flushFailed'
export const COMMIT_BATCHER_PENDING_CHANGED_EVENT = 'pendingChanged'

interface CommitChangeBase {
    onPersisted?: () => void
    saveReference?: OpenDocumentSaveReference
}

export interface CommitFileChange extends MarkdownFile, CommitChangeBase {
    kind: 'file'
}

export interface CommitCardChange extends CommitChangeBase {
    cardInternalId: string
    kind: 'card'
    path: string
    targetPath?: string
}

export interface CommitActionChange extends MarkdownFile, CommitChangeBase {
    actionId: string
    kind: 'action'
    onPathCommitted?: (fromPath: string, toPath: string) => void
    sourcePath: string
}

export interface CommitDiagramChange extends MarkdownFile, CommitChangeBase {
    diagramId: string
    kind: 'diagram'
    sourcePath: string
}

/** Repository path committed as it exists on disk at flush time; the renderer writes no content. */
export interface CommitPathChange extends CommitChangeBase {
    kind: 'path'
    path: string
}

export type CommitChange = CommitActionChange | CommitCardChange | CommitDiagramChange | CommitFileChange | CommitPathChange
type ContentChange = Exclude<CommitChange, CommitPathChange>

interface PendingChange {
    change: CommitChange
    messages: string[]
    onPathCommitted?: (fromPath: string, toPath: string) => void
}

interface SerializedChange {
    card: Card | null
    file: MarkdownFile
    sourcePath: string
}

function changeKey(change: CommitChange) {
    if (change.kind === 'card') return `card:${change.cardInternalId}`
    if (change.kind === 'action') return `action:${change.actionId}`
    if (change.kind === 'diagram') return `diagram:${change.diagramId}`
    if (change.kind === 'path') return `path:${change.path}`

    return `file:${change.path}`
}

function changeSourcePath(change: CommitChange) {
    if (change.kind === 'action' || change.kind === 'diagram') return change.sourcePath

    return change.path
}

function changeTargetPath(change: CommitChange) {
    return change.kind === 'card' ? change.targetPath ?? change.path : change.path
}

function serializeChange(change: ContentChange, cardOperations: CommitBatcherOperations): SerializedChange {
    const sourcePath = changeSourcePath(change)
    if (change.kind !== 'card') {
        const file = {
            content: change.content,
            ...(change.encoding ? { encoding: change.encoding } : {}),
            path: change.path,
            ...(change.sha ? { sha: change.sha } : {}),
        }

        return { card: null, file, sourcePath }
    }

    const card = cardOperations.requireCardByInternalId(change.cardInternalId)
    const file = { ...markdownParsingService.serializeCard(card), path: changeTargetPath(change) }

    return { card, file, sourcePath }
}

function rebaseChangeSource(change: CommitChange, sourcePath: string): CommitChange {
    if (change.kind === 'action' || change.kind === 'diagram') return { ...change, sourcePath }
    if (change.kind === 'card') return { ...change, path: sourcePath }

    return change
}

/** Serializes a batch and splits it into in-place files and moves for one storage request. */
function buildBatchRequest(branch: string, batch: Map<string, PendingChange>, cardOperations: CommitBatcherOperations) {
    const serializedChanges = new Map(
        [...batch.entries()].map(([key, { change }]) => [key, serializeChange(change, cardOperations)]),
    )
    const files: MarkdownFile[] = []
    const moves: MoveFile[] = []
    for (const [key] of batch) {
        const { file, sourcePath } = serializedChanges.get(key) as SerializedChange
        if (sourcePath === file.path) files.push(file)
        else {
            moves.push({
                content: file.content,
                ...(file.encoding ? { encoding: file.encoding } : {}),
                fromPath: sourcePath,
                ...(file.sha ? { sha: file.sha } : {}),
                toPath: file.path,
            })
        }
    }
    const request: WriteFilesRequest = { branch, files, ...(moves.length > 0 ? { moves } : {}) }

    return { request, serializedChanges }
}

function createCommitMessage(changes: Map<string, PendingChange>) {
    const messages = [...changes.values()].flatMap(({ messages: entryMessages }) => entryMessages)
    const distinctMessages = [...new Set(messages)]
    if (distinctMessages.length === 1) return distinctMessages[0]

    const body = distinctMessages.map((message) => `- ${message}`).join('\n')

    return `Update ${changes.size} files\n\n${body}`
}

export class CommitBatcher extends EventTarget {
    private activeFlush: Promise<void> | null
    private activeWrite: Promise<unknown> | null
    private automaticFlushDeferrals: number
    private readonly cardOperations: CommitBatcherOperations
    private readonly delayMsProvider: () => number
    private pendingBranch: string | null
    private pendingChanges: Map<string, PendingChange>
    private scheduledDelayId: DelayId | null

    constructor(cardOperations: CommitBatcherOperations, delayMsProvider: () => number = () => AUTO_COMMIT_DELAY_MS) {
        super()
        this.activeFlush = null
        this.activeWrite = null
        this.automaticFlushDeferrals = 0
        this.cardOperations = cardOperations
        this.delayMsProvider = delayMsProvider
        this.pendingBranch = null
        this.pendingChanges = new Map()
        this.scheduledDelayId = null
    }

    schedule(branch: string, changes: CommitChange[], message: string) {
        this.pendingBranch = branch
        changes.forEach((change) => this.addPendingChange(change, message))
        this.scheduleFlush()
    }

    schedulePathChange(
        branch: string,
        change: CommitCardChange,
        message: string,
        onPathCommitted: (fromPath: string, toPath: string) => void,
    ) {
        this.pendingBranch = branch
        this.addPendingChange(change, message, onPathCommitted)
        this.scheduleFlush()
    }

    private addPendingChange(
        change: CommitChange,
        message: string,
        onPathCommitted = change.kind === 'action' ? change.onPathCommitted : undefined,
    ) {
        const key = changeKey(change)
        const existingMessages = this.pendingChanges.get(key)?.messages ?? []
        const messages = existingMessages.includes(message) ? existingMessages : [...existingMessages, message]
        this.pendingChanges.set(key, { change, messages, onPathCommitted })
    }

    private scheduleFlush() {
        this.clearScheduledDelay()
        if (this.automaticFlushDeferrals > 0) {
            this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
            return
        }
        this.scheduledDelayId = window.setTimeout(this.createFlushCallback(), this.delayMsProvider())
        this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
    }

    /** Pauses timer-driven flushes while one caller adds fields that must share a card version. */
    deferAutomaticFlush() {

    }

    return files;
}

async function readTopLevelFolders(rootPath) {
    const entries = await fs.promises.readdir(rootPath, { withFileTypes: true });

    return entries
        .filter((entry) => entry.isDirectory() && entry.name !== GIT_FOLDER)
        .map((entry) => ({ name: entry.name, path: normalizePath(entry.name) }))
        .sort((left, right) => left.path.localeCompare(right.path));
}

/** Runs a renderer save under the project lock (outer) and the Git index lock (inner). */
function holdProjectMutation(rootPath, operation) {
    return projectOperationCoordinator.run(rootPath, () => withGitIndexMutation(rootPath, operation));
}

async function isTrackedFile(rootPath, repositoryPath) {
    try {
        await runGit(rootPath, ['ls-files', '--error-unmatch', '--', repositoryPath]);

        return true;
    } catch (error) {
        if (error && typeof error === 'object' && error.code === 1) return false;

        throw error;
    }
}

function createMissingWorkingFolderError(workingFolder) {
    const error = new Error(`Working folder is missing: ${workingFolder}`);
    error.code = 'missing-working-folder';
    error.workingFolder = workingFolder;

    return error;
}

/**
 * Creates every requested folder that is still missing, in one commit.
 *
 * Git cannot represent an empty directory, so each created folder gets a placeholder README.
 * Folders that already exist are left untouched.
 */
async function createProjectNow(project, folders) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const createdFolders = await createMissingProjectFolders(rootPath, folders);

    if (createdFolders.length > 0) {
        await runGit(rootPath, ['add', '--', ...createdFolders]);
        await commitStagedChanges(rootPath, `Create ${createdFolders.join(', ')} workspace`);
    }

    return project;
}

function createProject(project, folders) {
    if (!Array.isArray(folders)) throw new Error('Project folders must be an array');
    if (folders.length === 0) return Promise.resolve(project);

    const rootPath = requireRootPath(project);

    return holdProjectMutation(rootPath, () => createProjectNow(project, folders));
}

async function loadProject(project, workingFolder, excludedRootFolder) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const workingFolderPath = ensureInsideRoot(rootPath, path.join(rootPath, workingFolder));
    const excludedRootFolderPath = excludedRootFolder === undefined
        ? null
        : ensureInsideRoot(rootPath, path.join(rootPath, excludedRootFolder));

    if (!await pathExists(workingFolderPath)) {
        throw createMissingWorkingFolderError(workingFolder);
    }

    return {
        files: await readMarkdownFiles(rootPath, workingFolderPath, excludedRootFolderPath),
        workingFolder,
    };
}

async function loadProjectRoot(project, workingFolder) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    const workingFolderPath = ensureInsideRoot(rootPath, path.join(rootPath, workingFolder));

    if (!await pathExists(workingFolderPath)) {
        throw createMissingWorkingFolderError(workingFolder);
    }

    return {
        files: await readRootMarkdownFiles(rootPath, workingFolderPath),
        workingFolder,
    };
}

async function loadFile(project, filePath) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (typeof filePath !== 'string' || filePath.length === 0) throw new Error('Missing file path');
    if (!filePath.toLowerCase().endsWith(MARKDOWN_EXTENSION)) throw new Error('Only markdown files can be loaded this way');

    const fullPath = ensureInsideRoot(rootPath, path.join(rootPath, filePath));
    const content = await fs.promises.readFile(fullPath, 'utf8');

    return { content, path: normalizePath(path.relative(rootPath, fullPath)) };
}

async function loadTextFile(project, filePath) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (typeof filePath !== 'string' || filePath.length === 0) throw new Error('Missing text file path');

    const fullPath = ensureInsideRoot(rootPath, path.join(rootPath, filePath));
    const content = await fs.promises.readFile(fullPath, 'utf8');

    return { content, path: normalizePath(path.relative(rootPath, fullPath)) };
}

/**
 * Resolves a repository-relative file or folder path to its full path, requiring it to exist inside the project root.
 */
async function resolveExistingProjectEntry(project, entryPath) {
    const rootPath = requireRootPath(project);
    if (typeof entryPath !== 'string' || entryPath.length === 0) throw new Error('Missing project entry path');

    const fullPath = ensureInsideRoot(rootPath, path.join(rootPath, entryPath));
    try {
        await fs.promises.stat(fullPath);
    } catch {
        throw new Error(`Project entry does not exist: ${entryPath}`);
    }

    return fullPath;
}

async function loadProjectAsset(project, filePath) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (typeof filePath !== 'string' || filePath.length === 0) throw new Error('Missing project asset path');

    const extension = path.extname(filePath).toLowerCase();
    const contentType = PROJECT_ASSET_CONTENT_TYPES[extension];
    if (!contentType) throw new Error(`Unsupported project asset type: ${extension}`);

    const fullPath = ensureInsideRoot(rootPath, path.join(rootPath, filePath));
    const content = await fs.promises.readFile(fullPath);

    return {
        content: content.toString('base64'),
        contentType,
        encoding: 'base64',
        path: normalizePath(path.relative(rootPath, fullPath)),
    };
}

